if news_raw is not None:
    pub_col = next((c for c in news_raw.columns if c.lower() in ("published","published_at","timestamp","date")), None)
    if pub_col:
        ts = pd.to_datetime(news_raw[pub_col], errors="coerce", utc=True)
        daily = ts.dt.tz_convert("Asia/Kolkata").dt.date.value_counts().sort_index()
        if len(daily):
            fig, ax = plt.subplots()
            ax.bar(pd.to_datetime(list(daily.index)), daily.values, width=1.0, color="teal")
            ax.set_title("Daily News Article Count")
            ax.set_ylabel("# articles")
            save(fig, "02_news_volume")
        else:
            print("No valid publication timestamps parsed.")
    else:
        print("Could not find a publication column.")
else:
    print("news_raw not available.")

if md is not None:
    numeric = md.select_dtypes(include=[np.number]).copy()
    if len(numeric.columns) >= 2:
        corr = numeric.corr()
        fig, ax = plt.subplots(figsize=(12, 9))
        sns.heatmap(corr, cmap="RdBu_r", center=0, ax=ax, cbar_kws={"shrink": 0.7})
        ax.set_title("Feature Correlation Matrix")
        save(fig, "07_correlation")
    else:
        print("Not enough numeric columns for a correlation heatmap.")

if md is not None:
    ycol = next((c for c in md.columns if "next" in c.lower() and "return" in c.lower()), None)
    x1 = next((c for c in md.columns if c.lower()=="mean_sentiment" or ("mean" in c.lower() and "sentiment" in c.lower())), None)
    x2 = next((c for c in md.columns if "7d" in c.lower() and "sentiment" in c.lower()), None)

    if ycol and (x1 or x2):
        fig, axes = plt.subplots(1, 2, figsize=(14, 5))
        if x1:
            axes[0].scatter(md[x1], md[ycol], s=8, alpha=0.5, color="teal")
            axes[0].set_title(f"{x1} vs {ycol}")
            axes[0].set_xlabel(x1); axes[0].set_ylabel(ycol)
        else:
            axes[0].set_visible(False)
        if x2:
            axes[1].scatter(md[x2], md[ycol], s=8, alpha=0.5, color="crimson")
            axes[1].set_title(f"{x2} vs {ycol}")
            axes[1].set_xlabel(x2); axes[1].set_ylabel(ycol)
        else:
            axes[1].set_visible(False)
        save(fig, "08_sentiment_vs_return")
    else:
        print("Could not detect sentiment/return columns for scatter.")

if sel is not None:
    model_col = next((c for c in sel.columns if "model" in c.lower() or "config" in c.lower()), None)
    metric_col = next((c for c in sel.columns if c.lower() in ("mae","mean_mae") or "mae" in c.lower()), None)
    if model_col and metric_col:
        g = sel.groupby(model_col)[metric_col].mean().sort_values()
        if len(g):
            fig, ax = plt.subplots()
            g.plot(kind="barh", ax=ax, color="slateblue")
            ax.set_title(f"Mean {metric_col} by Model Configuration")
            ax.set_xlabel(metric_col)
            save(fig, "09_metric_by_model")
    else:
        print("Could not detect model/metric columns; inspect schema above.")
